fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    // Requires that the input list is non-empty
    // Requires: list.len() > 0
    // Ensures: result.len() == list.len()
    // Ensures: result is a rotation of list by n positions to the right
    // Decreases: list.len()
    // Invariant: list.len() > 0
    // Invariant: n < list.len() || n == 0
    // Invariant: rotation_amount == n % list.len()
    // Invariant: split_index == list.len() - rotation_amount
    // Invariant: new_list.len() == list.len()
    // Invariant: new_list[..rotation_amount] == list[split_index..]
    // Invariant: new_list[rotation_amount..] == list[..split_index]
    
    let len = list.len();
    assert!(len > 0); // Assert that the list is non-empty

    // Calculate the effective rotation amount
    let rotation_amount = n % len;
    if rotation_amount == 0 {
        return list.clone(); // No rotation needed
    }
    
    // Calculate the split point
    let split_index = len - rotation_amount;
    
    // Create the new rotated array
    let mut new_list = Vec::with_capacity(len);
    new_list.extend_from_slice(&list[split_index..]); // Suffix
    new_list.extend_from_slice(&list[..split_index]); // Prefix
    
    new_list
}